import tarfile
import os

def create_archive(archive_name, files):
    with tarfile.open(archive_name, 'w') as tar:
        for f in files:
            tar.add(f, arcname=os.path.basename(f))

def extract_archive(archive_name, output_dir):
    tar = tarfile.open(archive_name, 'r')
    os.chdir(output_dir)
    tar.extractall(path='../')
    tar.close()

def main():
    create_archive('data.tar.gz', ['data1.txt', 'data2.txt'])
    extract_archive('data.tar.gz', 'extracted')

if __name__ == '__main__':
    main()

