def extract_faces(img_path):
    img = face_recognition.load_image_file(img_path)
    face_locations = face_recognition.face_locations(img)
    faces = [img[location[0]:location[0]+location[2], location[1]:location[1]+location[3]] for location in face_locations]
    return faces

def identify_criminal(faces):
    known_criminals = [
        ('John Doe', face_recognition.load_image_file('john_doe.jpg')),
        ('Jane Doe', face_recognition.load_image_file('jane_doe.jpg'))
