import os
import shutil

def archive_files(files, output_path):
    with tarfile.open(output_path, 'w:gz') as tar:
        for f in files:
            tar.add(f, arcname=os.path.basename(f))

def restore_files(archive_path):
    tar = tarfile.open(archive_path, 'r:gz')
    tar.extractall(path='../')

def backup_files(files, backup_dir):
    archive_path = os.path.join(backup_dir, 'files.tar.gz')
    archive_files(files, archive_path)
    restore_files(archive_path)

