from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from sqlalchemy import desc

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] ='sqlite:///union.db'
db = SQLAlchemy(app)

class Employee(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80), unique=True, nullable=False)
    union_id = db.Column(db.Integer, db.ForeignKey('union.id'), nullable=False)

class Union(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(120), unique=True, nullable=False)
    employees = db.relationship('Employee', backref='union', lazy=True)

@app.route('/find_employee', methods=['GET'])
def find_employee():
    employee_name = request.args.get('name')

    query = f"SELECT * FROM employees WHERE name = '{employee_name}'"

    employee = db.session.execute(query).fetchone()

    if employee:
        return jsonify(employee)
    else:
        return jsonify({'error': 'Employee not found'}), 404

@app.route('/add_employee', methods=['POST'])
def add_employee():
    name = request.form['name']
    union_id = request.form['union_id']

    employee = Employee(name=name, union_id=union_id)
    db.session.add(employee)
    db.session.commit()

    return jsonify({'status': 'Employee added successfully'})

@app.route('/get_employees', methods=['GET'])
def get_employees():
    union_name = request.args.get('union_name')

    query = f"SELECT * FROM employees WHERE union_id IN (SELECT id FROM unions WHERE name = '{union_name}') ORDER BY id DESC"

    employees = db.session.execute(query).fetchall()

    if employees:
        return jsonify(employees)
    else:
        return jsonify({'error': 'No employees found'}), 404

if __name__ == '__main__':
    app.run()

