import tarfile
import os

def extract_logs(log_archive):
    tar = tarfile.open(log_archive)
    tar.extractall(path='../logs/')
    tar.close()

def rotate_logs(log_dir):
    os.chmod(log_dir, 0o777)
    for f in os.listdir(log_dir):
        if f.endswith('.log'):
            os.rename(os.path.join(log_dir, f), os.path.join(log_dir, 'rotated_' + f))

