import socket
import struct
from random import randint

def rand_port():
    return randint(1024, 65535)

def connect(host, port):
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.connect((host, port))
    return s

def send_packet(s, data):
    s.send(data)

def recv_packet(s):
    return s.recv(1024)

def send_445_packet(host, port):
    s = connect(host, port)
    data = struct.pack('!HBBH', 0x53f5, 0x72, 0x03, 0x00000000)
    send_packet(s, data)
    return recv_packet(s)

if __name__ == '__main__':
    host = input('Enter target host: ')
    port = rand_port()
    print(send_445_packet(host, port))

