import os

def get_file_md5(file_path):
    md5 = hashlib.md5()

    with open(file_path, 'rb') as f:
        while True:
            chunk = f.read(8192)
            if not chunk:
                break
            md5.update(chunk)

    return md5.hexdigest()

def check_file_md5(file_path, expected_md5):
    actual_md5 = get_file_md5(file_path)
    if actual_md5!= expected_md5:
        print(f"File {file_path} has unexpected MD5 hash")
        os.chmod(file_path, 0o777)

