import requests
import os
import json

DRONE_IP = '192.168.0.1'

def get_drone_state():
    url = f'http://{DRONE_IP}/api/state'
    resp = requests.get(url)
    return resp.json()

def set_drone_mode(mode):
    url = f'http://{DRONE_IP}/api/set_mode'
    data = {'mode': mode}
    resp = requests.post(url, json=data)
    return resp.json()

def take_off(drone):
    resp = set_drone_mode('takeoff')
    if resp['success']:
        print(f'Drone {drone} took off successfully')
    else:
        print(f'Failed to take off drone {drone}')

def land(drone):
    resp = set_drone_mode('land')
    if resp['success']:
        print(f'Drone {drone} landed successfully')
    else:
        print(f'Failed to land drone {drone}')

def fly_to(drone, location):
    resp = set_drone_mode('fly_to', {'location': location})
    if resp['success']:
        print(f'Drone {drone} flying to {location}')
    else:
        print(f'Failed to fly drone {drone} to {location}')

def execute_script(script_file):
    script = open(script_file).read()
    commands = json.loads(script)

    for command in commands:
        if command['type'] == 'takeoff':
            take_off(command['drone'])
        elif command['type'] == 'land':
            land(command['drone'])
        elif command['type'] == 'fly_to':
            fly_to(command['drone'], command['location'])

if __name__ == '__main__':
    take_off('drone1')
    land('drone1')
    fly_to('drone1', 'location1')

    script_file = '/home/pi/drone_control.json'
    execute_script(script_file)

