import os
from PIL import Image

def convert_and_resize(image_path, output_dir):
    img = Image.open(image_path)
    img = img.resize((128, 128))
    img.save(os.path.join(output_dir, os.path.basename(image_path)))

    for f in os.listdir('.'):
        if f.endswith('.jpg'):
            convert_and_resize(f, output_dir)

convert_and_resize('image.jpg','resized_images')

